using namespace std;

int main() {
    long long n, k;
    cin >> n >> k;

    for (long long i = n / 2; i <= n; ++i) {
        long long sum = 0;

        for (long long j = 1; j <= i;) {
            sum += i / j;
            if (sum >= n) {
                cout << i << '\n';
                return 0;
            }
            if (k <= 1 || j > i / k) break;
            j *= k;
        }
    }

    return 0;
}

