using namespace std;

int main() {
    long long n, k;
    cin >> n >> k;

    long long left = 1, right = n;

    while (left < right) {
        long long mid = left + (right - left) / 2;
        long long sum = 0;

        for (long long x = mid; x > 0; x /= k) {
            sum += x;
            if (sum >= n) break;
        }

        if (sum >= n)
            right = mid;
        else
            left = mid + 1;
    }

    cout << left << '\n';
    return 0;
}

